		WHERE  1=1

          AND  t1.rdf_nmsp_uri        = #{rdfNmspUri}


          AND  t1.rdf_nmsp_pfix        = #{rdfNmspPfix}


			AND  t1.rdf_nmsp_aply_mtcd  = #{rdfNmspAplyMtcd}

mapper.insert:

SELECT CONCAT('RNS', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_rdf_common') AS varchar), 4, '0'))	


INSERT /* SQL_ID: NamespaceMapper.insertRdfNamespace */
       INTO dtmeta.tb_rdf_namespace
	 ( rdf_nmsp_id
	, rdf_nmsp_pfix
	, rdf_nmsp_uri
	, rdf_nmsp_aply_mtcd
	, rdf_nmsp_regr_id
	, rdf_nmsp_regr_nm
	, rdf_nmsp_reg_dt
	, rdf_nmsp_amdr_id
	, rdf_nmsp_amdr_nm
	, rdf_nmsp_amd_dt
	 ) VALUES 
	 ( 			 
	   #{rdfNmspId}
	 , #{rdfNmspPfix}
	 , #{rdfNmspUri}
	 , #{rdfNmspAplyMtcd}
	 , #{rdfNmspRegrId}
	 , #{rdfNmspRegrNm}
	 , current_timestamp
	 , #{rdfNmspAmdrId}
	 , #{rdfNmspAmdrNm}
	 , current_timestamp
	 )

mapper.update:
		UPDATE /* SQL_ID: NamespaceMapper.updateRdfNamespace */
               dtmeta.tb_rdf_namespace
		   SET rdf_nmsp_uri					= #{changedRdfNmspUri}
             , rdf_nmsp_pfix				= #{changedRdfNmspPfix}
			 , rdf_nmsp_aply_mtcd  			=  #{rdfNmspAplyMtcd}
             , rdf_nmsp_amdr_id				= #{rdfNmspAmdrId}
             , rdf_nmsp_amdr_nm				= #{rdfNmspAmdrNm}
             , rdf_nmsp_amd_dt				= current_timestamp            
		 WHERE rdf_nmsp_id = #{rdfNmspId}

mapper.delete:
	DELETE  /* SQL_ID: NamespaceMapper.deleteRdfNamespace */
    FROM dtmeta.tb_rdf_namespace
    WHERE rdf_nmsp_id = #{rdfNmspId}

mapper.select:
	SELECT EXISTS (  /* SQL_ID: NamespaceMapper.isDuplicatedNamespaceUri */
		SELECT 1
		FROM dtmeta.tb_rdf_namespace
		WHERE rdf_nmsp_uri = #{rdfNmspUri}			

          AND rdf_nmsp_id != #{rdfNmspId}

	)

	SELECT EXISTS (  /* SQL_ID: NamespaceMapper.isDuplicatedNamespacePfix */
		SELECT 1
		FROM dtmeta.tb_rdf_namespace
		WHERE rdf_nmsp_pfix = #{rdfNmspPfix}

          AND rdf_nmsp_id != #{rdfNmspId}

	)

SELECT EXISTS (  /* SQL_ID: NamespaceMapper.isNamespaceExistInRdfClass */
	SELECT 1
	FROM dtmeta.tb_rdf_class
	WHERE rdf_nmsp_id = #{rdfNmspId}
)

SELECT EXISTS (  /* SQL_ID: NamespaceMapper.isNamespaceExistInRdfProperty */
	SELECT 1
	FROM dtmeta.tb_rdf_property
	WHERE rdf_nmsp_id = #{rdfNmspId}
)
